// Generated by Plot.

import type { Connect, Plugin } from "vite"

const heartbeatIntervalMs = 15_000

export const consolePipeHeartbeatMiddleware: Connect.NextHandleFunction = (request, response, next) => {
  if (request.url?.split("?")[0] === "/__tsd/console-pipe/sse") {
    // TanStack's console stream sends logs only. Comments keep Portal's idle
    // timer refreshed without introducing a console event.
    const timer = setInterval(() => {
      if (
        response.headersSent &&
        !response.writableEnded &&
        !response.destroyed &&
        String(response.getHeader("Content-Type")).startsWith("text/event-stream")
      ) {
        response.write(": heartbeat\n\n")
      }
    }, heartbeatIntervalMs)
    timer.unref()
    response.once("close", () => clearInterval(timer))
    response.once("finish", () => clearInterval(timer))
  }
  next()
}

export function consolePipeHeartbeat(): Plugin {
  return {
    name: "yorun-console-pipe-heartbeat",
    apply: "serve",
    enforce: "pre",
    configureServer(server) {
      server.middlewares.use(consolePipeHeartbeatMiddleware)
    },
  }
}
